function goalVideosMarkup(){return goalVideoClips.map((clip,i)=>`<figure><video controls playsinline preload="metadata" src="${escapeHTML(clip.url)}" aria-label="${i?'Supporting angle':'Main clip'}: ${escapeHTML(clip.name)}"></video><figcaption><span>${i?'SUPPORTING ANGLE':'THE MOMENT'}</span>${escapeHTML(clip.name)}</figcaption></figure>`).join('');}
function matchTagControl(id,label,placeholder){return `<div class="match-tag"><label class="story-check"><input type="checkbox" id="match-tag-${id}" data-match-tag="${id}"><span>${label}</span></label><label class="sr-only" for="match-${id}">${label} Instagram handle</label><input id="match-${id}" type="text" maxlength="31" pattern="@?[A-Za-z0-9_.]{1,30}" placeholder="${placeholder}" title="Use an Instagram handle, such as @yourname, without a URL."></div>`;}
function matchCategory(){return document.querySelector('input[name="match-category"]:checked')?.value||'Goals';}
function shareGoalsPage(category='Goals'){return `<div class="share-goals-page" id="match-intake-page">
<section class="match-heading"><p class="eyebrow">FROM YOUR PITCH TO OUR COMMUNITY.</p><div class="match-title-row"><h1>Share your<br><em>GOOOLS!</em></h1><div class="match-heading-note"><div class="match-replay-lockup">${strike()}<h2>A moment worth replaying.</h2></div><p>A team move. A last-minute winner. A match-saving stop. Let’s see it.</p><button class="text-link nav-underline" data-scroll="match-intake">Share your clip <span aria-hidden="true">↓</span></button></div></div><div class="match-context"><span>THE FINISH. THE BUILD-UP. THE FEELING.</span><span>GOOOL ATHLETICS / THE COMMUNITY</span></div></section>
<section class="match-how" aria-label="How it works"><div><span class="eyebrow">01 / SHARE</span><h3>Show us the moment.</h3><p>Choose the clip. Keep the build-up and celebration if you have them.</p></div><div><span class="eyebrow">02 / CREDIT</span><h3>Put a name to it.</h3><p>If featured, we’ll tag the submitter, player and club or program using the accounts you choose below.</p></div><div><span class="eyebrow">03 / REPLAY</span><h3>New goals. Every Monday.</h3><p>Submit by Sunday at 6 p.m. ET for consideration in Monday’s Goals of the Week. Our weekly top 10 lands on Instagram every Monday afternoon, with a monthly top 10 at the end of the month.</p></div></section>
<section class="match-intake" id="match-intake"><aside><p class="eyebrow">YOUR PITCH. YOUR MOMENT.</p><h2>Let the<br>clip talk.</h2><p>One moment per submission. Up to two supporting angles. Landscape or vertical, keep the action in view.</p><ul><li>MP4, MOV or WebM</li><li>Up to 100 MB per clip</li><li>Use footage you have permission to share</li></ul><p class="match-cutoff-note"><strong>Sunday at 6 p.m. ET is the weekly cutoff.</strong><br>Submit by then to be considered for Monday’s Goals of the Week. Later submissions roll into the following week’s review, so you won’t need to resubmit. Selection isn’t guaranteed.</p><p class="match-preview-note"><strong>Send your moment for review.</strong><br>Preview your clip and credit before submitting. Your files are saved privately and reviewed before any feature.</p></aside>
<form class="story-form match-form" id="match-form"><div class="match-form-section"><fieldset class="match-categories"><legend>What are you sharing?</legend><label><input type="radio" name="match-category" value="Goals" ${category==='Goals'?'checked':''}><span><strong>Goals</strong><small>The finish you want everyone to see.</small></span></label><label><input type="radio" name="match-category" value="Highlights" ${category==='Highlights'?'checked':''}><span><strong>Highlights</strong><small>Moments of sauce.</small><small>(Showcase your skills, or your friend getting sauced.)</small></span></label><label><input type="radio" name="match-category" value="Saves" ${category==='Saves'?'checked':''}><span><strong>Saves</strong><small>Keepers get their credit here.</small></span></label></fieldset><p class="eyebrow">01 / THE FOOTAGE</p><h3>Choose your clip.</h3><p id="match-video-help">Add your main clip first, followed by up to two extra angles.</p><input id="match-videos" class="sr-only" type="file" multiple accept="video/mp4,video/webm,video/quicktime,.mp4,.mov,.webm" aria-describedby="match-video-help match-video-status"><label class="btn depth-button video-picker-label" for="match-videos">Choose videos ${strike()}</label><p id="match-video-status" class="note" role="status" aria-live="polite">No clips selected.</p><div id="match-video-previews" class="match-video-previews"></div><button class="text-link nav-underline" type="button" id="match-clear" hidden>Remove clips</button></div>
<div class="match-form-section"><p class="eyebrow">02 / THE CREDIT</p><div class="story-field-row"><div><label for="match-name">Your name</label><input id="match-name" required maxlength="80" autocomplete="name" placeholder="First and last name"></div><div><label for="match-email">Your email <span>· private</span></label><input id="match-email" required type="email" maxlength="254" autocomplete="email" placeholder="For updates if featured"></div></div><label for="match-role">You’re sharing as</label><select id="match-role" required><option value="">Choose one</option><option>Player</option><option>Coach or team representative</option><option>Parent or guardian</option><option>Videographer</option><option>Friend / teammate</option></select><div class="story-field-row"><div><label for="match-player">Player credit</label><input id="match-player" required maxlength="80" placeholder="Name to appear with the clip"></div><div><label for="match-team">Club or program <span>· optional</span></label><input id="match-team" maxlength="100" placeholder="Club, school, college or Sunday league"></div></div><div class="story-field-row"><div><label for="match-location">City and state <span>· optional</span></label><input id="match-location" maxlength="100" placeholder="Newport, Rhode Island"></div></div><div class="match-shoutouts"><h3>Give them their moment.</h3><p>If your clip is featured, we’ll give a shoutout to the accounts you choose. Leave a box unchecked if you don’t want that account tagged.</p>${matchTagControl('submitter-handle','Tag me, the person submitting','@yourhandle')}${matchTagControl('program-handle','Tag the club, school or college program','@programhandle')}<label class="story-check"><input type="checkbox" id="match-friend"><span>Sharing someone else’s goal, highlight or save?</span></label><div id="match-friend-fields" hidden><p>You’ve got footage of a friend, teammate or player in your program scoring a goal, making a save or creating a moment of brilliance.</p>${matchTagControl('player-handle','Tag the player too, with their permission','@playerhandle')}<label class="story-check"><input type="checkbox" id="match-friend-permission"><span>The player agrees to this clip being shared and, if selected above, their account being tagged.</span></label></div><p class="note">Handles are optional. Entering one does not authorize a tag; select its checkbox if you want that account tagged. Use handles, not profile links.</p></div><label for="match-camera">Filmed by</label><input id="match-camera" required maxlength="100" placeholder="Name or organization that owns the footage"><label for="match-context">Tell us about the moment <span>· optional · 250 characters max</span></label><textarea id="match-context" maxlength="250" rows="1" placeholder="The match. The minute. Why this one mattered."></textarea></div>
<div class="match-form-section"><p class="eyebrow">03 / BEFORE YOU SHARE</p><p class="match-agreement-intro">The agreement explains permission to feature your clip, credit and tags, editing, and how to withdraw permission. <a class="agreement-link" href="/participation-agreement.html" data-match-agreement>Read the participation agreement</a>.</p><label class="story-check"><input id="match-adult" type="checkbox" required><span>I am 18 or older and am the player or an authorized person submitting this clip.</span></label><label class="story-check"><input id="match-rights" type="checkbox" required><span>I have the necessary rights to the footage and permission from people shown, including parent or guardian permission where required.</span></label><label class="story-check"><input id="match-permission" type="checkbox" required><span>I have read the <a href="/participation-agreement.html" class="agreement-link" data-match-agreement>participation agreement</a> with GOOOL Athletics LLC. I agree to its terms when I complete the final submission.</span></label><p id="match-form-status" class="form-error" role="status" aria-live="polite"></p><p class="note" id="match-acknowledgment-help">Check all three acknowledgments above to preview your submission. You can view the sample at any time.</p><div class="match-preview-actions"><button class="btn depth-button" id="match-preview-submit" type="submit" disabled aria-describedby="match-acknowledgment-help">Preview submission ${strike()}</button><button class="text-link nav-underline" type="button" id="match-sample-preview">See a sample preview</button></div><p class="note">Your email stays private. Tags are optional. No marketing signup is included. <a class="agreement-link" href="/intake-privacy.html" target="_blank" rel="noopener">How we handle your details</a>.</p></div></form></section>
<section class="match-month"><div><div class="match-schedule-stack" aria-label="Posting schedule"><div>${strike()}<span class="eyebrow">EVERY MONDAY</span></div><div>${strike()}<span class="eyebrow">MONTHLY TOP 10</span></div><div>${strike()}<span class="eyebrow">COMING SOON</span></div></div><h2>Your goal.<br>Our monthly top 10?</h2></div><div><p>From Sunday league to the college pitch. When the series launches, entries received by Sunday at 6 p.m. ET will be considered for the next day’s Goals of the Week. Later entries roll into the following week. We’ll post our weekly top 10 goals on Instagram every Monday afternoon, then bring together the strongest goals for our monthly top 10.</p><p>Highlights, goalkeeper saves and moments of brilliance will have their place too. Featured clips will credit the player and program, with tags for the accounts you authorize.</p><p>No clips featured yet. Who in your team could make the top 10?</p><button class="text-link nav-underline" data-scroll="match-intake">Share your moment <span aria-hidden="true">↑</span></button></div></section></div><section id="match-review" class="match-review" hidden tabindex="-1" aria-labelledby="match-review-title"></section><section id="match-confirmation" class="match-confirmation" hidden tabindex="-1" aria-labelledby="match-confirmation-title"></section><dialog id="match-terms-dialog" class="match-terms-dialog" aria-labelledby="match-terms-title"><div class="match-terms-header"><p class="eyebrow">GOOOL ATHLETICS LLC</p><button class="close-button" type="button" data-close aria-label="Close participation agreement">Close <span aria-hidden="true">×</span></button></div><h2 id="match-terms-title">${MATCH_TERMS.title}</h2><div class="match-terms-body">${matchAgreementHTML()}</div><div class="match-terms-actions"><a href="/participation-agreement.html" download="GOOOL-Participation-Agreement.html" class="text-link nav-underline">Download a copy</a><button type="button" class="btn depth-button" data-close>Return to form</button></div></dialog>`;}
function syncMatchTags(){
 ['submitter-handle','program-handle','player-handle'].forEach(id=>{const check=$('#match-tag-'+id),field=$('#match-'+id);const on=check.checked&&(id!=='player-handle'||$('#match-friend').checked);field.disabled=false;field.required=on;if(!on)field.setCustomValidity('');});
 const friend=$('#match-friend').checked;$('#match-friend-fields').hidden=!friend;$('#match-friend-permission').required=friend;$('#match-friend-permission').disabled=!friend;
 $('#match-team').required=$('#match-tag-program-handle').checked;
}
function syncMatchCategory(){
 const keeper=matchCategory()==='Saves';
 $('label[for="match-player"]').textContent=keeper?'Goalkeeper credit':'Player credit';
 $('#match-player').placeholder=keeper?'Goalkeeper’s name to appear with the save':'Name to appear with the clip';
}
function matchAcknowledgmentsComplete(){return ['adult','rights','permission'].every(id=>$('#match-'+id)?.checked);}
function syncMatchPreviewAccess(){
 const complete=matchAcknowledgmentsComplete();
 const button=$('#match-preview-submit');if(button)button.disabled=!complete;
 if(complete)$('#match-form-status').textContent='';
}
function requireMatchAcknowledgments(){
 if(matchAcknowledgmentsComplete())return true;
 $('#match-intake-page').hidden=false;$('#match-review').hidden=true;$('#match-confirmation').hidden=true;
 $('#match-form-status').textContent='Please check all three acknowledgments before previewing your submission.';
 const missing=['adult','rights','permission'].find(id=>!$('#match-'+id).checked);
 $('#match-'+missing).scrollIntoView({behavior:'instant',block:'center'});$('#match-'+missing).focus({preventScroll:true});
 return false;
}
function showMatchReview({sample=false,category=matchCategory()}={}){
 if(!sample&&!requireMatchAcknowledgments())return;
 category=['Goals','Highlights','Saves'].includes(category)?category:'Goals';
 const submitLabel=category==='Highlights'?'Submit highlight / sauce':category==='Saves'?'Submit your save':'Submit your goal';
 const sampleData={name:'Sample Submitter',email:'submitter@example.com',role:'Player',player:category==='Saves'?'Sample Goalkeeper':'Sample Player',team:'Example College Program',location:'Newport, Rhode Island','submitter-handle':'@sample_submitter','program-handle':'@sample_program','player-handle':'@sample_player',camera:'Example team media crew',context:category==='Saves'?'A close-range shot, a fingertip save and a second stop on the rebound. Keeping the team in the game.':category==='Highlights'?'A quick turn under pressure, a run past two defenders and a pass that opened up the play. A moment worth replaying.':'We won the ball near our own box, worked it through midfield and finished the move at the far post. A team goal from start to finish.'};
 const tag=(id)=>sample?sampleData[id]:$('#match-tag-'+id).checked?$('#match-'+id).value.trim():'Not requested';
 const val=id=>sample?sampleData[id]:$('#match-'+id).value.trim();const review=$('#match-review');review.dataset.category=category;review.dataset.sample=String(sample);
 review.innerHTML=`<p class="eyebrow">SHARE YOUR GOOOLS! / REVIEW</p><span class="coming-label">${sample?'ILLUSTRATIVE SAMPLE · NOT SUBMITTED':'PREVIEW · NOT SUBMITTED'}</span><h1 id="match-review-title">One more look.</h1><p>${sample?'Example details only. Your form entries have not been changed.':'Check the clip and the credit before sharing.'}</p><div class="match-review-grid"><div class="match-video-previews">${sample?'<div class="match-sample-video"><p class="eyebrow">VIDEO PREVIEW</p><p>Your selected clip plays here.</p><span>Sample layout · no video attached</span></div>':goalVideosMarkup()}</div><div class="match-review-credit"><p class="eyebrow">${category==='Saves'?'THE GOALKEEPER':'THE PLAYER'}</p><h2>${escapeHTML(val('player'))}</h2><p>${escapeHTML(val('team'))||'Independent player'}</p><dl>${[['Submitted by',val('name')],['Email · private',val('email')],['Sharing as',val('role')],['Category',category],['Location',val('location')||'Not added'],['Submitter tag',tag('submitter-handle')],['Club / program tag',tag('program-handle')],['Player tag',sample?sampleData['player-handle']:$('#match-friend').checked?tag('player-handle'):'Not requested'],['Filmed by',val('camera')]].map(([k,v])=>`<dt>${k}</dt><dd>${escapeHTML(v)}</dd>`).join('')}</dl><p class="eyebrow">THE MOMENT</p><p class="match-moment-copy">${escapeHTML(val('context'))||'Letting the clip tell the story.'}</p>${sample?'':`<p class="note">Your submission will record your acceptance of these terms. Agreement version: ${MATCH_TERMS.version}. <a href="/participation-agreement.html" class="agreement-link" data-match-agreement>Read agreement</a>.</p>`}</div></div>${sample?`<div class="match-sample-end"><button class="text-link nav-underline" id="match-edit" type="button"><span aria-hidden="true">←</span> Back to form</button><p class="note">Example agreement status; no checkbox has been selected for you. No live consent recorded. Nothing will be sent.<br>Agreement version: ${MATCH_TERMS.version}. <a href="/participation-agreement.html" class="agreement-link" data-match-agreement>Read agreement</a>.</p></div>`:`<div class="match-review-actions"><button class="btn depth-button" id="match-edit" type="button">Edit submission ${strike()}</button><button class="btn depth-button match-submit" id="match-finish" type="button" aria-label="${submitLabel}">${category==='Highlights'?`<span>Submit highlight</span>${strike()}<span>sauce</span>`:submitLabel}</button></div>`} ${sample?'':'<p class="note" id="match-send-status" role="status" aria-live="polite">Your clips and details will be saved for review when you submit.</p>'}`;
 $$('#match-intake-page video').forEach(v=>v.pause());$('#match-intake-page').hidden=true;review.hidden=false;document.title='Review your clip | GOOOL Athletics';window.scrollTo({top:0,behavior:'instant'});review.focus({preventScroll:true});
}
