function videoSelectionError(files){
 if(files.length>3)return 'Choose up to 3 videos at a time.';
 if(files.some(file=>!file.size||file.size>100*1024*1024))return 'Each video must be between 1 byte and 100 MB.';
 if(files.some(file=>!(/\.(mp4|mov|webm)$/i.test(file.name))||(file.type&&!['video/mp4','video/webm','video/quicktime'].includes(file.type))))return 'Choose MP4, MOV or WebM video files.';
 return '';
}
