function setupGoalIntroReveal(){
 goalIntroObserver?.disconnect();goalIntroObserver=null;
 const section=document.querySelector('.goal-intro-editorial');
 if(!section||!('IntersectionObserver' in window)||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 section.classList.add('intro-reveal-ready');
 goalIntroObserver=new IntersectionObserver(entries=>{
  if(entries.some(entry=>entry.isIntersecting)){section.classList.add('intro-revealed');goalIntroObserver?.disconnect();}
 },{threshold:.12});
 goalIntroObserver.observe(section);
}
