document.addEventListener('change',async event=>{
 if(event.target.matches('[name="kit-numbers"]'))syncKit();
 const match=event.target.id.match(/^kit-(crest|numbers)-file$/);if(!match)return;
 const kind=match[1],input=event.target,file=input.files[0];if(!file)return;
 const revision=++kitUploadRevision[kind];
 const status=document.querySelector('#kit-'+kind+'-status');const error=kitFileError(file);
 const reject=message=>{if(status.isConnected&&revision===kitUploadRevision[kind]){status.textContent=message+(kitFiles[kind]?' Your previous file is still selected.':'');input.value='';}};
 if(error){reject(error);return;}
 let url=null;
 try {
 const ext=file.name.split('.').pop().toLowerCase();const bytes=new Uint8Array(await file.slice(0,8).arrayBuffer());
 if(ext==='png'&&bytes.join(',')!=='137,80,78,71,13,10,26,10'){reject('This file is not a valid PNG. Try saving it again.');return;}
 if(['jpg','jpeg'].includes(ext)&&(bytes[0]!==255||bytes[1]!==216||bytes[2]!==255)){reject('This file is not a valid JPG. Try saving it again.');return;}
 if(ext==='pdf'&&String.fromCharCode(...bytes.slice(0,5))!=='%PDF-'){reject('This file is not a valid PDF. Try saving it again.');return;}
 if(ext==='svg'){const text=await file.text();if(!kitSafeSvg(text)){reject('This SVG contains features we cannot preview. Export a PNG or PDF instead.');return;}url=URL.createObjectURL(new Blob([text],{type:'image/svg+xml'}));}
 else if(ext==='pdf')url=await kitPdfPreview(file);
 else url=URL.createObjectURL(new Blob([await file.arrayBuffer()],{type:ext==='png'?'image/png':'image/jpeg'}));
 if(!status.isConnected||revision!==kitUploadRevision[kind]){if(url)URL.revokeObjectURL(url);return;}
 if(kitFiles[kind]?.url)URL.revokeObjectURL(kitFiles[kind].url);
 kitFiles[kind]={name:file.name,size:file.size,url,file};input.setCustomValidity('');
 status.textContent='File selected: '+file.name+'. Saved in this tab only.';
 document.querySelector('[data-kit-remove="'+kind+'"]').hidden=false;syncKit();if(kind==='crest')setKitView('front');
 }catch{if(url)URL.revokeObjectURL(url);reject('We could not read that file. Please try another.');}
});
